@import "tailwindcss";
@import "uniwind";

@theme {
  --color-background: hsl(216.0 17.2% 94.3%);
  --color-foreground: hsl(220.0 18.2% 12.9%);
  --color-card: hsl(0 0% 100.0%);
  --color-card-foreground: hsl(220.0 18.2% 12.9%);
  --color-popover: hsl(0 0% 100.0%);
  --color-popover-foreground: hsl(220.0 18.2% 12.9%);
  --color-primary: hsl(232.4 58.8% 55.3%);
  --color-primary-foreground: hsl(0 0% 100.0%);
  --color-secondary: hsl(218.2 15.9% 86.5%);
  --color-secondary-foreground: hsl(220.0 18.2% 12.9%);
  --color-muted: hsl(218.2 15.9% 86.5%);
  --color-muted-foreground: hsl(220.0 10.4% 54.9%);
  --color-accent: hsl(225.0 20.0% 92.2%);
  --color-accent-foreground: hsl(223.4 17.6% 32.4%);
  --color-destructive: hsl(5.6 63.4% 46.1%);
  --color-destructive-foreground: hsl(0 0% 100.0%);
  --color-border: hsl(218.2 18.6% 88.4%);
  --color-input: hsl(217.5 16.3% 80.8%);
  --color-ring: hsl(232.4 58.8% 55.3%);
  --radius-lg: 0.5rem;
  --radius-md: calc(0.5rem - 2px);
  --radius-sm: calc(0.5rem - 4px);
}

@layer theme {
  :root {
    @variant light {
  --color-background: hsl(216.0 17.2% 94.3%);
  --color-foreground: hsl(220.0 18.2% 12.9%);
  --color-card: hsl(0 0% 100.0%);
  --color-card-foreground: hsl(220.0 18.2% 12.9%);
  --color-popover: hsl(0 0% 100.0%);
  --color-popover-foreground: hsl(220.0 18.2% 12.9%);
  --color-primary: hsl(232.4 58.8% 55.3%);
  --color-primary-foreground: hsl(0 0% 100.0%);
  --color-secondary: hsl(218.2 15.9% 86.5%);
  --color-secondary-foreground: hsl(220.0 18.2% 12.9%);
  --color-muted: hsl(218.2 15.9% 86.5%);
  --color-muted-foreground: hsl(220.0 10.4% 54.9%);
  --color-accent: hsl(225.0 20.0% 92.2%);
  --color-accent-foreground: hsl(223.4 17.6% 32.4%);
  --color-destructive: hsl(5.6 63.4% 46.1%);
  --color-destructive-foreground: hsl(0 0% 100.0%);
  --color-border: hsl(218.2 18.6% 88.4%);
  --color-input: hsl(217.5 16.3% 80.8%);
  --color-ring: hsl(232.4 58.8% 55.3%);
    }

    @variant dark {
  --color-background: hsl(222.0 29.4% 6.7%);
  --color-foreground: hsl(222.4 25.4% 86.9%);
  --color-card: hsl(220.0 25.0% 14.1%);
  --color-card-foreground: hsl(222.4 25.4% 86.9%);
  --color-popover: hsl(220.0 25.4% 11.6%);
  --color-popover-foreground: hsl(222.4 25.4% 86.9%);
  --color-primary: hsl(232.3 79.6% 71.2%);
  --color-primary-foreground: hsl(0 0% 100.0%);
  --color-secondary: hsl(221.3 24.2% 12.9%);
  --color-secondary-foreground: hsl(222.4 25.4% 86.9%);
  --color-muted: hsl(221.3 24.2% 12.9%);
  --color-muted-foreground: hsl(221.3 14.0% 44.7%);
  --color-accent: hsl(220.0 23.1% 17.8%);
  --color-accent-foreground: hsl(222.4 25.4% 86.9%);
  --color-destructive: hsl(0.0 73.3% 66.3%);
  --color-destructive-foreground: hsl(0 0% 100.0%);
  --color-border: hsl(221.1 23.5% 15.9%);
  --color-input: hsl(221.7 21.1% 21.4%);
  --color-ring: hsl(232.0 76.6% 74.9%);
    }
  }
}
